    if (this._lassoFill)
      this._lassoFill.destroy();
    this._lassoLine = new Graphics;
    this._lassoFill = new Graphics;
    this._lassoData = null;
    const lasso = new Container;
    lasso.label = "lasso";
    lasso.eventMode = "none";
    lasso.sortableChildren = false;
    lasso.visible = false;
    this.lasso = lasso;
