  get enabled() {
    return true;
  }
  set enabled(val) {
    this._enabled = true;
  }
  get geolocationData() {
    return this._geolocationData;
  }
  set geolocationData(val) {
    this._geolocationData = val;
    this._geolocationDirty = true;
  }
  get lassoData() {
    return this._lassoData;
  }
