// modules/ui/sections/background_offset.js
function uiSectionBackgroundOffset(context2) {
  const l10n = context2.systems.l10n;
  const imagery = context2.systems.imagery;
  const section = uiSection(context2, "background-offset").label(l10n.t("background.fix_misalignment")).disclosureContent(renderDisclosureContent);
  const DIRECTIONS = [
    ["top", [0, -0.5]],
    ["left", [-0.5, 0]],
    ["right", [0.5, 0]],
    ["bottom", [0, 0.5]]
  ];
  function updateValue() {
    const meters = geoOffsetToMeters(imagery.offset);
    const x3 = +meters[0].toFixed(2);
    const y3 = +meters[1].toFixed(2);
    context2.container().selectAll(".nudge-inner-rect").select("input").classed("error", false).property("value", `${x3},${y3}`);
    context2.container().selectAll(".nudge-reset").classed("disabled", x3 === 0 && y3 === 0);
  }
  function resetOffset() {
    imagery.offset = [0, 0];
    updateValue();
  }
  function nudge(d2) {
    imagery.nudge(d2);
    updateValue();
  }
  function inputOffset(d3_event) {
    let input2 = select_default2(d3_event.target);
    let val = input2.node().value;
    if (val === "")
      return resetOffset();
    val = val.replace(/;/g, ",").split(",").map((n2) => {
      return !isNaN(n2) && n2;
    });
    if (val.length !== 2 || !val[0] || !val[1]) {
      input2.classed("error", true);
      return;
    }
    imagery.offset = geoMetersToOffset(val);
    updateValue();
  }
  function pointerdown(d3_event) {
    if (d3_event.button !== 0)
      return;
    let input2 = context2.container().selectAll(".nudge-inner-rect > input").node();
    if (d3_event.target === input2)
      return;
    let origin = [d3_event.clientX, d3_event.clientY];
    const pointerId = d3_event.pointerId || "mouse";
    context2.container().append("div").attr("class", "nudge-surface");
    select_default2(window).on("pointermove.drag-bg-offset", pointermove).on("pointerup.drag-bg-offset", pointerup).on("pointercancel.drag-bg-offset", pointerup);
    function pointermove(d3_event2) {
      if (pointerId !== (d3_event2.pointerId || "mouse"))
        return;
      const latest = [d3_event2.clientX, d3_event2.clientY];
      const delta = [
        -(origin[0] - latest[0]) / 4,
        -(origin[1] - latest[1]) / 4
      ];
      origin = latest;
      nudge(delta);
    }
    function pointerup(d3_event2) {
      if (pointerId !== (d3_event2.pointerId || "mouse"))
        return;
      if (d3_event2.button !== 0)
        return;
      context2.container().selectAll(".nudge-surface").remove();
      select_default2(window).on(".drag-bg-offset", null);
    }
  }
  function renderDisclosureContent(selection2) {
    let container = selection2.selectAll(".nudge-container").data([0]);
    let containerEnter = container.enter().append("div").attr("class", "nudge-container");
    containerEnter.append("div").attr("class", "nudge-instructions").text(l10n.t("background.offset"));
    let nudgeWrapEnter = containerEnter.append("div").attr("class", "nudge-controls-wrap");
    let nudgeEnter = nudgeWrapEnter.append("div").attr("class", "nudge-outer-rect").on("pointerdown", pointerdown);
    nudgeEnter.append("div").attr("class", "nudge-inner-rect").append("input").attr("type", "text").on("change", inputOffset);
    nudgeWrapEnter.append("div").selectAll("button").data(DIRECTIONS).enter().append("button").attr("class", (d2) => `${d2[0]} nudge`).attr("tabindex", -1).on("click", (d3_event, d2) => nudge(d2[1]));
    nudgeWrapEnter.append("button").attr("title", l10n.t("background.reset")).attr("class", "nudge-reset disabled").on("click", (d3_event) => {
      d3_event.preventDefault();
      resetOffset();
    }).call(uiIcon("#rapid-icon-" + (l10n.isRTL ? "redo" : "undo")));
    updateValue();
  }
  imagery.on("imagerychange", updateValue);
  return section;
}

