// modules/ui/intro/rapid.js
function uiIntroRapid(context2, curtain) {
  const dispatch2 = dispatch_default2("done");
  const chapter = { title: "intro.rapid.title" };
  const editor = context2.systems.editor;
  const l10n = context2.systems.l10n;
  const map4 = context2.systems.map;
  const rapid = context2.systems.rapid;
  const scene = context2.systems.gfx.scene;
  const ui = context2.systems.ui;
  const tulipLaneID = "w-516";
  const tulipLaneExtent = new Extent([-85.62991, 41.95568], [-85.627, 41.95638]);
  let _chapterCancelled = false;
  let _rejectStep = null;
  let _onModeChange = null;
  function _isTulipLaneSelected() {
    if (!["select", "select-osm"].includes(context2.mode?.id))
      return false;
    const ids = context2.selectedIDs();
    return ids.length === 1 && ids[0] === tulipLaneID;
  }
  function _isTulipLaneAccepted() {
    const graph = editor.staging.graph;
    return graph.hasEntity(tulipLaneID);
  }
  function runAsync(currStep) {
    if (_chapterCancelled)
      return Promise.reject();
    if (typeof currStep !== "function")
      return Promise.resolve();
    return currStep().then((nextStep) => runAsync(nextStep)).catch((e3) => {
      if (e3 instanceof Error)
        console.error(e3);
      return runAsync(currStep);
    });
  }
  function welcomeAsync() {
    context2.enter("browse");
    editor.restoreCheckpoint("initial");
    scene.enableLayers("rapid");
    rapid.enableDatasets("rapid_intro_graph");
    const loc = tulipLaneExtent.center();
    const msec = transitionTime(loc, map4.center());
    if (msec > 0)
      curtain.hide();
    return map4.setMapParamsAsync(loc, 18.5, 0, msec).then(() => new Promise((resolve, reject) => {
      _rejectStep = reject;
      const rtl = l10n.isRTL ? "-rtl" : "";
      curtain.reveal({
        revealSelector: ".intro-nav-wrap .chapter-rapid",
        tipHtml: helpHtml(context2, "intro.rapid.start", {
          rapid: icon(`#rapid-logo-rapid-wordmark${rtl}`, "pre-text rapid")
        }),
        buttonText: l10n.t("intro.ok"),
        buttonCallback: () => resolve(showHideRoadsAsync)
      });
    }));
  }
  function showHideRoadsAsync() {
    return new Promise((resolve, reject) => {
      _rejectStep = reject;
      const rtl = l10n.isRTL ? "-rtl" : "";
      curtain.reveal({
        revealSelector: "button.rapid-features",
        tipHtml: helpHtml(context2, "intro.rapid.ai_roads", {
          rapid: icon(`#rapid-logo-rapid-wordmark${rtl}`, "pre-text rapid")
        }),
        buttonText: l10n.t("intro.ok"),
        buttonCallback: () => resolve(selectRoadAsync)
      });
    });
  }
  function selectRoadAsync() {
    context2.enter("browse");
    editor.restoreCheckpoint("initial");
    ui.togglePanes();
    scene.enableLayers("rapid");
    rapid.enableDatasets("rapid_intro_graph");
    return new Promise((resolve, reject) => {
      _rejectStep = reject;
      _onModeChange = () => resolve(acceptRoadAsync);
      select_default2(".inspector-wrap").on("wheel.intro", eventCancel);
      curtain.reveal({
        revealExtent: tulipLaneExtent,
        tipHtml: helpHtml(context2, "intro.rapid.select_road")
      });
    }).finally(() => {
      _onModeChange = null;
      select_default2(".inspector-wrap").on("wheel.intro", null);
    });
  }
  function acceptRoadAsync() {
    return delayAsync().then(() => new Promise((resolve, reject) => {
      _rejectStep = reject;
      if (!_isTulipLaneSelected()) {
        resolve();
        return;
      }
      _onModeChange = resolve;
      curtain.reveal({
        revealSelector: ".rapid-inspector-choice-accept",
        tipHtml: helpHtml(context2, "intro.rapid.add_road")
      });
    })).then(() => {
      if (editor.getUndoAnnotation()?.type === "rapid_accept_feature") {
        return roadAcceptedAsync;
      } else {
        return selectRoadAsync;
      }
    }).finally(() => {
      _onModeChange = null;
    });
  }
  function roadAcceptedAsync() {
    return delayAsync().then(() => new Promise((resolve, reject) => {
      _rejectStep = reject;
      if (!_isTulipLaneAccepted()) {
        resolve(selectRoadAsync);
        return;
      }
      if (!_isTulipLaneSelected())
        context2.enter("select-osm", { selection: { osm: [tulipLaneID] } });
      _onModeChange = reject;
      const rtl = l10n.isRTL ? "-rtl" : "";
      curtain.reveal({
        revealExtent: tulipLaneExtent,
        tipHtml: helpHtml(context2, "intro.rapid.add_road_not_saved_yet", {
          rapid: icon(`#rapid-logo-rapid-wordmark${rtl}`, "pre-text rapid")
        }),
        buttonText: l10n.t("intro.ok"),
        buttonCallback: () => resolve(showIssuesButtonAsync)
      });
    })).finally(() => {
      _onModeChange = null;
    });
  }
  function showIssuesButtonAsync() {
    if (!_isTulipLaneAccepted())
      return Promise.resolve(selectRoadAsync);
    if (!_isTulipLaneSelected())
      context2.enter("select-osm", { selection: { osm: [tulipLaneID] } });
    const issuesButton = select_default2("div.map-control.issues-control > button");
    return new Promise((resolve, reject) => {
      _rejectStep = reject;
      _onModeChange = reject;
      curtain.reveal({
        revealNode: issuesButton.node(),
        tipHtml: helpHtml(context2, "intro.rapid.open_issues")
      });
      issuesButton.on("click.intro", () => resolve(showLintAsync));
    }).finally(() => {
      _onModeChange = null;
      issuesButton.on("click.intro", null);
    });
  }
  function showLintAsync() {
    return delayAsync().then(() => new Promise((resolve, reject) => {
      _rejectStep = reject;
      if (!_isTulipLaneAccepted()) {
        resolve(selectRoadAsync);
        return;
      }
      if (!_isTulipLaneSelected())
        context2.enter("select-osm", { selection: { osm: [tulipLaneID] } });
      const label = select_default2("li.issue.severity-warning");
      curtain.reveal({
        revealNode: label.node(),
        revealPadding: 5,
        tipHtml: helpHtml(context2, "intro.rapid.new_lints"),
        buttonText: l10n.t("intro.ok"),
        buttonCallback: () => resolve(undoRoadAddAsync)
      });
    }));
  }
  function undoRoadAddAsync() {
    if (!_isTulipLaneAccepted())
      return Promise.resolve(selectRoadAsync);
    if (!_isTulipLaneSelected())
      context2.enter("select-osm", { selection: { osm: [tulipLaneID] } });
    const undoButton = select_default2(".map-toolbar button.undo-button");
    return new Promise((resolve, reject) => {
      _rejectStep = reject;
      curtain.reveal({
        revealNode: undoButton.node(),
        tipHtml: helpHtml(context2, "intro.rapid.undo_road_add", { button: icon("#rapid-icon-undo", "inline") })
      });
      undoButton.on("click.intro", () => resolve(afterUndoRoadAddAsync));
    }).finally(() => {
      undoButton.on("click.intro", null);
    });
  }
  function afterUndoRoadAddAsync() {
    if (_isTulipLaneAccepted())
      return Promise.resolve(selectRoadAsync);
    ui.togglePanes();
    return new Promise((resolve, reject) => {
      _rejectStep = reject;
      curtain.reveal({
        revealExtent: tulipLaneExtent,
        tipHtml: helpHtml(context2, "intro.rapid.undo_road_add_aftermath"),
        buttonText: l10n.t("intro.ok"),
        buttonCallback: () => resolve(selectRoadAgainAsync)
      });
    });
  }
  function selectRoadAgainAsync() {
    context2.enter("browse");
    editor.restoreCheckpoint("initial");
    scene.enableLayers("rapid");
    rapid.enableDatasets("rapid_intro_graph");
    const loc = tulipLaneExtent.center();
    const msec = transitionTime(loc, map4.center());
    if (msec > 0)
      curtain.hide();
    return map4.setMapParamsAsync(loc, 18.5, 0, msec).then(() => new Promise((resolve, reject) => {
      _rejectStep = reject;
      _onModeChange = () => {
        if (!context2.selectedIDs().includes(tulipLaneID))
          return;
        resolve(ignoreRoadAsync);
      };
      curtain.reveal({
        revealExtent: tulipLaneExtent,
        tipHtml: helpHtml(context2, "intro.rapid.select_road_again")
      });
    })).finally(() => {
      _onModeChange = null;
    });
  }
  function ignoreRoadAsync() {
    return delayAsync().then(() => new Promise((resolve, reject) => {
      _rejectStep = reject;
      if (!_isTulipLaneSelected()) {
        resolve();
        return;
      }
      _onModeChange = resolve;
      curtain.reveal({
        revealSelector: ".rapid-inspector-choice-ignore",
        tipHtml: helpHtml(context2, "intro.rapid.ignore_road")
      });
    })).then(() => {
      if (editor.getUndoAnnotation()?.type === "rapid_ignore_feature") {
        return playAsync;
      } else {
        return selectRoadAgainAsync;
      }
    }).finally(() => {
      _onModeChange = null;
    });
  }
  function playAsync() {
    dispatch2.call("done");
    curtain.reveal({
      revealSelector: ".ideditor",
      tipSelector: ".intro-nav-wrap .chapter-startEditing",
      tipHtml: helpHtml(context2, "intro.rapid.done", { next: l10n.t("intro.startediting.title") }),
      buttonText: l10n.t("intro.ok"),
      buttonCallback: () => curtain.reveal({ revealSelector: ".ideditor" })
    });
    return Promise.resolve();
  }
  chapter.enter = () => {
    scene.enableLayers("rapid");
    _chapterCancelled = false;
    _rejectStep = null;
    _onModeChange = null;
    context2.on("modechange", _modeChangeListener);
    runAsync(welcomeAsync).catch((e3) => {
      if (e3 instanceof Error)
        console.error(e3);
    }).finally(() => {
      context2.off("modechange", _modeChangeListener);
    });
    function _modeChangeListener(...args) {
      if (typeof _onModeChange === "function")
        _onModeChange(...args);
    }
  };
  chapter.exit = () => {
    scene.disableLayers("rapid");
    rapid.disableDatasets("rapid_intro_graph");
    _chapterCancelled = true;
    if (_rejectStep) {
      _rejectStep();
      _rejectStep = null;
    }
  };
  chapter.restart = () => {
    chapter.exit();
    chapter.enter();
  };
  return utilRebind(chapter, dispatch2, "on");
}

// modules/ui/intro/intro.js
var chapterUi = {
  welcome: uiIntroWelcome,
  navigation: uiIntroNavigation,
  point: uiIntroPoint,
  area: uiIntroArea,
  line: uiIntroLine,
  building: uiIntroBuilding,
  rapid: uiIntroRapid,
  startEditing: uiIntroStartEditing
};
var chapterFlow = [
  "welcome",
  "navigation",
  "point",
  "area",
  "line",
  "building",
  "rapid",
  "startEditing"
];
function uiIntro(context2, skipToRapid) {
  const assets = context2.systems.assets;
  const editor = context2.systems.editor;
  const imagery = context2.systems.imagery;
  const l10n = context2.systems.l10n;
  const map4 = context2.systems.map;
  const mapwithai = context2.services.mapwithai;
  const osm = context2.services.osm;
  const rapid = context2.systems.rapid;
  const scene = context2.systems.gfx.scene;
  const storage = context2.systems.storage;
  const urlhash = context2.systems.urlhash;
  const ui = context2.systems.ui;
  let _introGraph = {};
  let _rapidGraph = {};
  let _original = {};
  let _resume = {};
  let _progress = [];
  let _currChapter;
  let _buttons;
  let _curtain;
  let _navwrap;
  function intro(selection2) {
    Promise.all([
      assets.loadAssetAsync("intro_rapid_graph"),
      assets.loadAssetAsync("intro_graph")
    ]).then((values) => {
      const rapidData = values[0].introRapidGraph;
      const introData = values[1].introGraph;
      for (const [id, data] of Object.entries(rapidData)) {
        if (!_rapidGraph[id]) {
          _rapidGraph[id] = createOsmEntity(context2, localize(context2, data));
        }
      }
      for (const [id, data] of Object.entries(introData)) {
        if (!_introGraph[id]) {
          _introGraph[id] = createOsmEntity(context2, localize(context2, data));
        }
      }
      selection2.call(_startIntro);
    });
  }
  function _startIntro(selection2) {
    _resume = {
      urlhash: urlhash.pause(),
      osm: osm?.pause(),
      mapwithai: mapwithai?.pause()
    };
    context2.container().classed("inIntro", true);
    context2.inIntro = true;
    context2.enter("browse");
    _original = {
      hash: window.location.hash,
      transform: context2.viewport.transform.props,
      brightness: imagery.brightness,
      baseLayer: imagery.baseLayerSource(),
      overlayLayers: imagery.overlayLayerSources(),
      layersEnabled: new Set,
      datasetsAdded: new Set(rapid._addedDatasetIDs),
      datasetsEnabled: new Set(rapid._enabledDatasetIDs),
      edits: editor.toJSON()
    };
    for (const [layerID, layer] of scene.layers) {
      if (layer.enabled) {
        _original.layersEnabled.add(layerID);
      }
    }
    scene.onlyLayers(["background", "osm", "labels"]);
    rapid.removeDatasets(rapid._addedDatasetIDs);
    rapid.addDatasets("rapid_intro_graph");
    const introSource = imagery.getSourceByID("Bing");
    imagery.baseLayerSource(introSource);
    _original.overlayLayers.forEach((d2) => imagery.toggleOverlayLayer(d2));
    imagery.brightness = 1;
    ui.Sidebar.expand(false);
    _curtain = new UiCurtain(context2);
    selection2.call(_curtain.enable);
    storage.setItem("walkthrough_started", "yes");
    const storedProgress = storage.getItem("walkthrough_progress") || "";
    _progress = storedProgress.split(";").filter(Boolean);
    const chapters = chapterFlow.map((chapterID, i2) => {
      const s2 = chapterUi[chapterID](context2, _curtain).on("done", () => {
        _buttons.filter((d2) => d2.title === s2.title).classed("finished", true);
        _progress.push(chapterID);
        storage.setItem("walkthrough_progress", utilArrayUniq(_progress).join(";"));
        if (i2 < chapterFlow.length - 1) {
          const nextID = chapterFlow[i2 + 1];
          context2.container().select(`button.chapter-${nextID}`).classed("next", true);
        } else {
          _finish();
        }
      });
      return s2;
    });
    _navwrap = selection2.append("div").attr("class", "intro-nav-wrap fillD");
    _navwrap.append("svg").attr("class", "intro-nav-wrap-logo").append("use").attr("xlink:href", "#rapid-logo-walkthrough");
    const buttonwrap = _navwrap.append("div").attr("class", "joined").selectAll("button.chapter");
    _buttons = buttonwrap.data(chapters).enter().append("button").attr("class", (d2, i2) => `chapter chapter-${chapterFlow[i2]}`).on("click", _enterChapter);
    _buttons.append("span").text((d2) => l10n.t(d2.title));
    _buttons.append("span").attr("class", "status").call(uiIcon(l10n.isRTL ? "#rapid-icon-backward" : "#rapid-icon-forward", "inline"));
    context2.resetAsync().then(() => {
      editor.merge(Object.values(_introGraph));
      mapwithai?.merge("rapid_intro_graph", Object.values(_rapidGraph));
      editor.setCheckpoint("initial");
      _enterChapter(null, chapters[skipToRapid ? 6 : 0]);
    });
  }
  function _enterChapter(d3_event, newChapter) {
    if (_currChapter)
      _currChapter.exit();
    context2.enter("browse");
    _currChapter = newChapter;
    _currChapter.enter();
    _buttons.classed("next", false).classed("active", (d2) => d2.title === _currChapter.title);
  }
  function _finish() {
    const incomplete = utilArrayDifference(chapterFlow, _progress);
    if (!incomplete.length) {
      storage.setItem("walkthrough_completed", "yes");
    }
    rapid.removeDatasets("rapid_intro_graph");
    rapid.addDatasets(_original.datasetsAdded);
    rapid.enableDatasets(_original.datasetsEnabled);
    _curtain.disable();
    _navwrap.remove();
    for (const [layerID, layer] of scene.layers) {
      layer.enabled = _original.layersEnabled.has(layerID);
    }
    imagery.baseLayerSource(_original.baseLayer);
    _original.overlayLayers.forEach((d2) => imagery.toggleOverlayLayer(d2));
    imagery.brightness = _original.brightness;
    map4.transform(_original.transform);
    window.location.replace(_original.hash);
    context2.container().classed("inIntro", false);
    context2.inIntro = false;
    _resume.osm?.();
    _resume.mapwithai?.();
    _resume.urlhash();
    context2.resetAsync().then(() => {
      if (_original.edits) {
        return editor.fromJSONAsync(_original.edits);
      } else {
        return Promise.resolve();
      }
    });
  }
  return intro;
}

