// modules/ui/UiApiStatus.js
class UiApiStatus {
  constructor(context2) {
    this.context = context2;
    this._apiStatus = null;
    this._backupStatus = null;
    this._gfxStatus = null;
    this.$parent = null;
    this.render = this.render.bind(this);
    this._onApiStatusChange = this._onApiStatusChange.bind(this);
    this._onBackupStatusChange = this._onBackupStatusChange.bind(this);
    this._onGfxStatusChange = this._onGfxStatusChange.bind(this);
    const editor = context2.systems.editor;
    const gfx = context2.systems.gfx;
    editor.on("backupstatuschange", this._onBackupStatusChange);
    gfx.on("statuschange", this._onGfxStatusChange);
    const osm = context2.services.osm;
    if (osm) {
      window.setInterval(() => {
        if (this._apiStatus === "ratelimit") {
          this.render();
        }
      }, 1000);
      window.setInterval(() => {
        osm.reloadApiStatus();
      }, 90000);
      osm.reloadApiStatus();
      osm.on("apistatuschange", this._onApiStatusChange);
    }
  }
  render($parent = this.$parent) {
    if ($parent instanceof selection_default) {
      this.$parent = $parent;
    } else {
      return;
    }
    const context2 = this.context;
    const l10n = context2.systems.l10n;
    const osm = context2.services.osm;
    const rateLimit = osm?.getRateLimit();
    let $apiStatus = $parent.selectAll(".api-status").data([0]);
    const $$apiStatus = $apiStatus.enter().append("div").attr("class", "api-status");
    $apiStatus = $apiStatus.merge($$apiStatus);
    $apiStatus.html("");
    if (this._gfxStatus === "contextlost") {
      $apiStatus.text(l10n.t("status.message.contextlost") + " ");
      $apiStatus.append("a").attr("href", "#").text(l10n.t("status.dismiss")).on("click.dismiss", (e3) => {
        e3.preventDefault();
        this._gfxStatus = null;
        this.render();
      });
    } else if (this._apiStatus === "readonly") {
      $apiStatus.text(l10n.t("status.message.readonly"));
    } else if (this._apiStatus === "offline") {
      $apiStatus.text(l10n.t("status.message.offline"));
    } else if (this._apiStatus === "ratelimit" && rateLimit) {
      $apiStatus.text(l10n.t("status.message.ratelimit", { seconds: rateLimit.remaining }));
      if (osm && !osm.authenticated()) {
        $apiStatus.append("a").attr("href", "#").attr("target", "_blank").call(uiIcon("#rapid-icon-out-link", "inline")).append("span").text(l10n.t("login")).on("click.login", (e3) => {
          e3.preventDefault();
          osm.authenticate();
          this._apiStatus = "online";
        });
      }
    } else if (this._apiStatus === "error") {
      $apiStatus.text(l10n.t("status.message.error") + " ");
      if (osm) {
        $apiStatus.append("a").attr("href", "#").text(l10n.t("status.retry")).on("click.retry", (e3) => {
          e3.preventDefault();
          osm.throttledReloadApiStatus();
        });
      }
    } else if (this._backupStatus === "error") {
      $apiStatus.text(l10n.t("status.message.local_storage_full"));
    }
  }
  _onApiStatusChange(apiStatus) {
    this._apiStatus = apiStatus ?? "error";
    this.render();
  }
  _onBackupStatusChange(wasSuccessful) {
    this._backupStatus = wasSuccessful ? "ok" : "error";
    this.render();
  }
  _onGfxStatusChange(status) {
    if (status === "contextlost") {
      this._gfxStatus = status;
      this.render();
    }
  }
}
