// modules/ui/UiScale.js
var MAXLENGTH = 180;
var TICKHEIGHT = 8;

class UiScale {
  constructor(context2) {
    this.context = context2;
    const l10n = context2.systems.l10n;
    const gfx = context2.systems.gfx;
    this._isImperial = !l10n.isMetric;
    this.$parent = null;
    this.$wrap = null;
    this.render = this.render.bind(this);
    this.rerender = () => this.render();
    this.toggleUnits = this.toggleUnits.bind(this);
    this.updateScale = this.updateScale.bind(this);
    this._deferredUpdateScale = throttle_default(this.updateScale, 100);
    gfx.on("draw", this._deferredUpdateScale);
  }
  render($parent = this.$parent) {
    if ($parent instanceof selection_default) {
      this.$parent = $parent;
    } else {
      return;
    }
    let $wrap = $parent.selectAll(".scale-wrap").data([0]);
    const $$wrap = $wrap.enter().append("div").attr("class", "scale-wrap").on("click", this.toggleUnits);
    $$wrap.append("svg").attr("class", "scale").append("path").attr("class", "scale-path");
    $$wrap.append("div").attr("class", "scale-text");
    this.$wrap = $wrap = $wrap.merge($$wrap);
    this.updateScale();
  }
  updateScale() {
    if (!this.$wrap)
      return;
    const context2 = this.context;
    const l10n = context2.systems.l10n;
    const viewport = context2.viewport;
    const bottom = viewport.dimensions[1];
    const loc1 = viewport.unproject([0, bottom]);
    const loc2 = viewport.unproject([MAXLENGTH, bottom]);
    const lat = (loc2[1] + loc1[1]) / 2;
    const conversion = this._isImperial ? 3.28084 : 1;
    const dist = geoLonToMeters(loc2[0] - loc1[0], lat) * conversion;
    let buckets;
    if (this._isImperial) {
      buckets = [5280000, 528000, 52800, 5280, 500, 50, 5, 1];
    } else {
      buckets = [5000000, 500000, 50000, 5000, 500, 50, 5, 1];
    }
    let scaleDistance = 0;
    for (const val of buckets) {
      if (dist >= val) {
        scaleDistance = Math.floor(dist / val) * val;
        break;
      } else {
        scaleDistance = +dist.toFixed(2);
      }
    }
    const dLon = geoMetersToLon(scaleDistance / conversion, lat);
    const scaleWidth = Math.round(viewport.project([loc1[0] + dLon, loc1[1]])[0]);
    const scaleHeight = TICKHEIGHT;
    const scaleText = l10n.displayLength(scaleDistance / conversion, this._isImperial);
    const [w3, h2] = [scaleWidth + 2, scaleHeight + 2];
    this.$wrap.select(".scale").attr("width", `${w3}px`).attr("height", `${h2}px`).attr("viewBox", `0 0 ${w3} ${h2}`);
    this.$wrap.select(".scale-path").attr("d", `M0.5,0.5 v${scaleHeight} h${scaleWidth} v${-scaleHeight}`);
    this.$wrap.select(".scale-text").text(scaleText);
  }
  toggleUnits() {
    this._isImperial = !this._isImperial;
    this.updateScale();
  }
}
