    this._mapRect = null;
    this._needWidth = {};
    this._resizeTimeout = null;
    this._showsMapRouletteMenu = false;
    this.ApiStatus = null;
    this.AuthModal = null;
    this.Defs = null;
    this.EditMenu = null;
    this.MapRouletteMenu = null;
    this.Flash = null;
    this.Fullscreen = null;
    this.MapFooter = null;
    this.MapToolbar = null;
    this.Overmap = null;
    this.Shortcuts = null;
    this.Sidebar = null;
    this.InfoCards = null;
    this.Minimap = null;
    this.PhotoViewer = null;
