    this._mapRect = curr;
    const dtop = prev.top - curr.top;
    const dright = prev.right - curr.right;
    const dbottom = prev.bottom - curr.bottom;
    const dleft = prev.left - curr.left;
    const [dw, dh] = [dleft + dright, dtop + dbottom];
    if (dw || dh) {
      map4.pan([dw / 2, dh / 2]);
    }
