    this.drawWayID = null;
    this.drawNodeID = null;
    this.lastNodeID = null;
    this.firstNodeID = null;
    this._insertIndex = undefined;
    this._lastPoint = null;
    this._selectedData.clear();
    eventManager.setCursor("crosshair");
