      $head.selectAll("#rapideditor-pannellum-css").data([0]).enter().append("link").attr("id", "rapideditor-pannellum-css").attr("rel", "stylesheet").attr("crossorigin", "anonymous").attr("href", assets.getAssetURL("pannellum_css")).on("load", loaded).on("error", reject);
