    for (const loc of poly) {
      extent2.extendSelf(viewport.wgs84ToWorld(loc));
    }
    let minDist = Infinity;
    const hits = spatial.getDataAtBox("streetside-images", extent2.bbox());
    for (const hit of hits) {
      const bubble = hit.contents;
      if (bubble.id === selected.id)
        continue;
      if (!geomPointInPolygon(bubble.loc, poly))
        continue;
      let dist = vecLength(bubble.loc, selected.loc);
      const theta = (selected.props.ca ?? 0) - (bubble.props.ca ?? 0);
      const minTheta = Math.min(Math.abs(theta), 360 - Math.abs(theta));
      if (minTheta > 20) {
        dist += 5;
      }
      if (dist < minDist) {
        nextID = bubble.id;
        minDist = dist;
      }
    }
