    source11.inflight.set(tileID, controller);
    const [x5, y3, z2] = tile.xyz;
    let _fetch;
    if (source11.pmtiles) {
      _fetch = source11.pmtiles.getZxy(z2, x5, y3, controller.signal).then((response) => response?.data);
    } else {
      const url = source11.template.replace("{x}", x5.toString()).replace("{y}", y3.toString()).replace(/\{[t-]y\}/, (Math.pow(2, z2) - y3 - 1).toString()).replace(/\{z(oom)?\}/, z2.toString()).replace(/\{switch:([^}]+)\}/, function(s2, r2) {
        const subdomains = r2.split(",");
        return subdomains[(x5 + y3) % subdomains.length];
      });
      _fetch = fetch(url, { signal: controller.signal }).then(utilFetchResponse);
    }
    return _fetch.then((buffer) => {
      source11.loaded.set(tileID, tile);
      this._parseTileBuffer(source11, tile, buffer);
    }).catch((err2) => {
      if (err2.name === "AbortError")
        return;
      if (err2 instanceof Error)
        console.error(err2);
    }).finally(() => {
      source11.inflight.delete(tileID);
    });
